(()=>{const root=document.documentElement,seq=document.querySelector('.sequence'),stage=document.querySelector('.sequence-sticky'),hero=document.querySelector('.product-hero'),core=document.querySelector('.core-visual'),chapters=[...document.querySelectorAll('.chapter')],steps=[...document.querySelectorAll('[data-step]')];let queued=false,progress=0;function update(){queued=false;const range=document.documentElement.scrollHeight-innerHeight;root.style.setProperty('--reading',range>0?scrollY/range:0);const motion=window.paMotion!==false&&!matchMedia('(max-height:500px) and (orientation:landscape)').matches;if(hero){const y=hero.getBoundingClientRect().top;if(motion&&y>-innerHeight&&y<innerHeight)hero.style.setProperty('--hero-float',Math.max(-35,Math.min(35,-y*.07))+'px');else hero.style.setProperty('--hero-float','0px')}if(seq&&stage&&motion){const top=seq.getBoundingClientRect().top,offset=innerWidth<=700?75:94;progress=Math.max(0,Math.min(1,(offset-top)/Math.max(1,seq.offsetHeight-stage.offsetHeight)));const index=Math.min(2,Math.floor(progress*3));stage.dataset.scene=index;chapters.forEach((c,i)=>{c.classList.toggle('active',i===index);c.setAttribute('aria-hidden',i===index?'false':'true')});steps.forEach((s,i)=>{s.classList.toggle('active',i===index);s.setAttribute('aria-current',i===index?'step':'false')});stage.querySelector('.sequence-count').textContent='0'+(index+1)+' / 03';core.style.setProperty('--turn',(progress*155-25)+'deg');window.paSceneProgress=progress}else if(!motion){chapters.forEach(c=>c.removeAttribute('aria-hidden'))}}function request(){if(!queued){queued=true;requestAnimationFrame(update)}}addEventListener('scroll',request,{passive:true});addEventListener('resize',request);document.getElementById('motion')?.addEventListener('click',()=>requestAnimationFrame(update));steps.forEach(a=>a.addEventListener('click',e=>{e.preventDefault();if(!seq)return;const i=+a.dataset.step,offset=innerWidth<=700?75:94;const y=scrollY+seq.getBoundingClientRect().top-offset+(seq.offsetHeight-stage.offsetHeight)*(i/3+.08);scrollTo({top:y,behavior:window.paMotion?'smooth':'auto'})}));if(matchMedia('(hover:hover)').matches)document.querySelectorAll('.module-card').forEach(card=>{card.addEventListener('pointermove',e=>{if(!window.paMotion)return;const r=card.getBoundingClientRect();card.style.setProperty('--mx',(e.clientX-r.left)/r.width*100+'%');card.style.setProperty('--my',(e.clientY-r.top)/r.height*100+'%')})});update()})();
